    /// The value in the most readable SI-prefixed form of the base unit, in
    /// steps of 1000: the largest unit not exceeding the value (`µPa`, `mPa`, `Pa`, `kPa`, `MPa`, `GPa`).
    /// Zero, NaN and infinities are shown in the base unit.
    #[inline]
    pub fn auto_unit(self) -> crate::InUnit<T, PressureUnit> {
        const SCALE: [(f64, PressureUnit); 6] = [
            (1e9, PressureUnit::Gigapascal),
            (1000000.0, PressureUnit::Megapascal),
            (1000.0, PressureUnit::Kilopascal),
            (1.0, PressureUnit::Pascal),
            (0.001, PressureUnit::Millipascal),
            (1e-6, PressureUnit::Micropascal),
        ];
        let magnitude = self.0.abs();
        if magnitude == T::from_f64(0.0) || !magnitude.is_finite() {
            return self.in_unit(PressureUnit::Pascal);
        }
        let mut unit = SCALE[SCALE.len() - 1].1;
        for (factor, candidate) in SCALE {
            if magnitude >= T::from_f64(factor) {
                unit = candidate;
                break;
            }
        }
        self.in_unit(unit)
    }

